import random
from feal import f_function
samples=[random.getrandbits(32) for _ in range(200)]
for mask in range(16):
    d=0
    for i in range(4):
        if mask>>i &1: d|=0x80<<(8*i)
    outs={f_function(x)^f_function(x^d) for x in samples}
    print(hex(d), len(outs), hex(next(iter(outs))) if len(outs)==1 else sorted(hex(o) for o in list(outs)[:4]))
